import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import { createStarlightTypeDocPlugin } from 'starlight-typedoc';

// API reference generated by TypeDoc from the package's three public entry
// points. typedoc/entries/ re-exports each entry point under its import
// specifier, and typedoc/tsconfig.json maps @noctcore/harness to its sources,
// so the site builds without building the package first. The output is written
// to src/content/docs/reference/api/ at build time and gitignored.
const [harnessTypeDoc, harnessApiGroup] = createStarlightTypeDocPlugin();
const typeDoc = {
  name: '@noctcore/harness',
  excludePrivate: true,
  excludeInternal: true,
  readme: 'none',
  // Module pages named README.md are dropped by the plugin when no readme is
  // configured, while the package page still links to them; index.md is kept.
  entryFileName: 'index',
  sort: ['kind', 'alphabetical'],
  // Source links are left out: TypeDoc could not resolve repo-relative paths
  // through the entry re-exports, and a bare file name helps nobody.
  disableSources: true,
};

// Project Pages for github.com/noctcore/harness serve from
// https://noctcore.github.io/harness/. A wrong `base` still builds green and
// 404s every asset, which is why scripts/check-build.ts reads the emitted HTML.
export default defineConfig({
  site: 'https://noctcore.github.io',
  base: '/harness',
  trailingSlash: 'always',
  integrations: [
    starlight({
      title: '@noctcore/harness',
      logo: {
        light: './src/assets/brand/logo-light.svg',
        dark: './src/assets/brand/logo-dark.svg',
        replacesTitle: true,
      },
      favicon: '/favicon.svg',
      customCss: ['./src/styles/tokens.css', './src/styles/theme.css', './src/styles/landing.css'],
      components: { Hero: './src/components/Hero.astro' },
      expressiveCode: {
        themes: ['github-dark-default', 'github-light'],
        // Long install commands wrap instead of hiding their tail behind a scrollbar.
        defaultProps: { overridesByLang: { 'sh,bash,shell': { wrap: true } } },
        styleOverrides: {
          borderRadius: 'var(--nc-radius)',
          borderColor: 'var(--nc-line-soft)',
          codeBackground: 'var(--nc-code-bg)',
          codeFontFamily: 'var(--nc-font-mono)',
          uiFontFamily: 'var(--nc-font)',
          frames: {
            editorBackground: 'var(--nc-code-bg)',
            editorTabBarBackground: 'var(--nc-bg-raised)',
            editorActiveTabBackground: 'var(--nc-code-bg)',
            editorActiveTabIndicatorTopColor: 'var(--nc-accent)',
            editorActiveTabIndicatorBottomColor: 'transparent',
            editorTabBarBorderBottomColor: 'var(--nc-line-soft)',
            terminalBackground: 'var(--nc-code-bg)',
            terminalTitlebarBackground: 'var(--nc-bg-raised)',
            terminalTitlebarBorderBottomColor: 'var(--nc-line-soft)',
            frameBoxShadowCssValue: 'none',
          },
        },
      },
      description:
        'Hold a TypeScript repo to its own rules in any CI: a check runner, whole-repo lint-meta rules and pinned linters.',
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/noctcore/harness' }],
      plugins: [
        harnessTypeDoc({
          entryPoints: [
            './typedoc/entries/harness.ts',
            './typedoc/entries/rules.ts',
            './typedoc/entries/pinned-tools.ts',
            './typedoc/entries/ci.ts',
          ],
          tsconfig: './typedoc/tsconfig.json',
          output: 'reference/api',
          sidebar: { label: 'API', collapsed: true },
          typeDoc,
        }),
      ],
      editLink: { baseUrl: 'https://github.com/noctcore/harness/edit/main/site/' },
      sidebar: [
        { label: 'Overview', link: '/' },
        { label: 'Getting started', link: '/start/getting-started/' },
        {
          label: 'Guides',
          items: [
            { label: 'The manifest and the runner', link: '/guides/manifest-and-runner/' },
            { label: 'Writing a lint-meta rule', link: '/guides/writing-a-rule/' },
            { label: 'Baselines and the ratchet', link: '/guides/baselines/' },
            { label: 'The rule catalog', link: '/guides/rule-catalog/' },
            { label: 'Pinned tools', link: '/guides/pinned-tools/' },
            {
              label: 'Dockerfiles, migrations and images',
              link: '/guides/hadolint-squawk-trivy/',
            },
            { label: 'CI helpers', link: '/guides/ci-helpers/' },
          ],
        },
        {
          label: 'Rules',
          items: [
            { label: 'Using the rules', link: '/rules/' },
            { label: 'lockfile-registry-resolutions', link: '/rules/lockfile-registry-resolutions/' },
            { label: 'single-version-dependencies', link: '/rules/single-version-dependencies/' },
            {
              label: 'only-built-dependencies-have-scripts',
              link: '/rules/only-built-dependencies-have-scripts/',
            },
            { label: 'pnpm-patch-ledger', link: '/rules/pnpm-patch-ledger/' },
            {
              label: 'github-actions-secret-no-install',
              link: '/rules/github-actions-secret-no-install/',
            },
            {
              label: 'github-actions-security-no-cancel',
              link: '/rules/github-actions-security-no-cancel/',
            },
          ],
        },
        {
          label: 'Reference',
          items: [{ label: 'CLI', link: '/reference/cli/' }, harnessApiGroup],
        },
        { label: 'FAQ', link: '/faq/' },
      ],
    }),
  ],
  vite: {
    // Starlight renders some Markdown through Satteri, whose native binding is an
    // optional dependency that Bun's isolated linker keeps next to `satteri` only.
    // Leave it external in Astro 7's prerender environment.
    environments: { prerender: { resolve: { external: ['satteri'] } } },
  },
});
